const FAILURE = {
  normal_empty: "A successful command with no match, no rows, or no device is an empty observation; save it as empty and do not turn it into a failure.",
  model_correctable: "For an invalid path, option, format, or query, read stderr, correct the input, and retry with a new command and recorded revision.",
  transient_retryable: "For a busy process, temporary network error, or service startup race, retain logs and retry within the job budget after checking for duplicate side effects.",
  missing_condition: "If a required file, device, authorization, service, network permission, or architecture is absent, record inconclusive/needs_human with the missing condition.",
  permanent: "For unsupported input, corrupt artifacts, an unavailable binary, or an unrecoverable exit, stop and record permanent_failure with stderr and the exact command."
};

const entry = (imageKey, spec) => ({
  image_key: imageKey,
  id: spec.id,
  kind: spec.kind ?? "tool",
  agent_visible: spec.agent_visible ?? !spec.implementation_only,
  implementation_only: spec.implementation_only ?? false,
  version: spec.version ?? "unspecified",
  version_source: spec.version_source ?? "source inventory requires confirmation",
  commands: spec.commands ?? [],
  usage_scenario: spec.usage_scenario ?? "Use this entry only when its input and required runtime context match the task.",
  selection_basis: spec.selection_basis ?? "Choose it after checking the image manifest and input type; do not substitute a tool with a different evidence model.",
  prerequisites: spec.prerequisites ?? ["Read the frozen job image manifest and work under the job workspace."],
  minimal_invocation: spec.minimal_invocation ?? "Run the command with an explicit input and output location.",
  common_parameters: spec.common_parameters ?? ["--help", "explicit input path", "explicit output path"],
  output_interpretation: spec.output_interpretation ?? "Treat stdout/stderr and exit code as observations. A successful process does not prove a security conclusion by itself.",
  failure_handling: { ...FAILURE, ...(spec.failure_handling ?? {}) },
  composition_flow: spec.composition_flow ?? "Save the raw output, normalize only with a documented transformation, then pass the artifact to the next tool or verifier.",
  evidence_retention: spec.evidence_retention ?? ["Exact command and arguments", "image key and digest", "tool version", "stdout/stderr", "exit code", "input and output hashes"],
  version_limits_side_effects_cleanup: spec.version_limits_side_effects_cleanup ?? "Version is bound to the image manifest. Use a workspace-local output directory, bound resources, and remove temporary files after evidence is retained.",
  verification_status: spec.verification_status ?? "source_declared_unexecuted",
  verification_note: spec.verification_note ?? "Entry is derived from the pinned source manifest; this catalog run did not build or execute the image.",
  ...(spec.device_required === undefined ? {} : { device_required: spec.device_required }),
  ...(spec.requires_egress === undefined ? {} : { requires_egress: spec.requires_egress }),
  ...(spec.covers === undefined ? {} : { covers: spec.covers })
});

