const capability = (imageKey, id, version, source, commands, usage, selection, invocation, params, extra = {}) => def(imageKey, id, version, source, commands, usage, selection, invocation, params, { kind: "capability", ...extra });

const makeImage = (imageKey, sourceFiles, inheritedFrom, defs, sections) => {
  const entries = defs;
  return {
    image_key: imageKey,
    manual_path: `/opt/deepsonar/manuals/images/${imageKey}/index.md`,
    self_contained: true,
    inherited_from: inheritedFrom,
    source_files: sourceFiles,
    sections,
    entries,
    entry_count: entries.length,
    agent_visible_entry_count: entries.filter((x) => x.agent_visible).length,
    implementation_only_entry_count: entries.filter((x) => x.implementation_only).length
  };
};

